style.css:
@-moz-document domain("miruro.tv"), domain("miruro.online"), domain("miruro.to") {
:root.dark-mode {
        --oppposite: #ffffff;
        --global-primary-bg: #1C1B22;
        --global-primary-bg-tr: rgba(8, 8, 8, .9);
        --global-secondary-bg: #1b1b1b;
        --global-tertiary-bg: #222222;
        --global-div: #2F2F38;
        --global-div-tr: #27272E;
        --global-div-tr-navbar: #24242B;
        --global-border: #2A2A32;
        --global-text-blue: #3db4f2;
        --global-text: #e8e8e8;
        --global-text-muted: #696969;
        --global-text-muted-2: #222222;
        --global-text-muted-3: #aaaaaa;
        --global-card-bg: #2F2F38;
        --global-card-title-bg: #151515;
        --global-card-shadow: rgba(255, 255, 255, .05);
        --global-filter-shadow: rgba(255, 255, 255, .05);
        --global-filter-extra-shadow: rgba(0, 0, 0, 1);
        --global-shadow: rgba(0, 0, 0, .6);
        --global-primary-skeleton: rgba(85, 85, 85, .1);
        --global-secondary-skeleton: rgba(85, 85, 85, .3);
        --global-button-bg: #2F2F38;
        --global-button-hover-bg: #292929;
        --global-button-text: #ebebeb;
        --global-button-shadow: rgba(0, 0, 0, .6);
        --global-genre-button-bg: #222222;
        --global-border-radius: .3rem;
        --primary-accent: #8080cf;
        --primary-accent-bg: #595991;
    }
}
